function onEdit(e) {
  var inicio = e && typeof e.r53Inicio_ === 'number' ? e.r53Inicio_ : Date.now();
  if (!e || !e.range) return;
  if (r53RestaurarVersaoPublica_(e)) { continuarPaleta_(inicio,null,false,e.range); return; }
  if (typeof salarioIntegrarMissao_ === 'function' && salarioIntegrarMissao_(e,onEdit)) return;
  if (typeof salarioEditar_ === 'function' && salarioEditar_(e)) return;
  var aba = e.range.getSheet().getName();
  // A troca de paleta voltou pra cá em 25/09/2026, em passos que cabem nos 30 segundos, pra
  // funcionar em toda cópia sem ninguém autorizar nada. Ver convergirPaleta_.
  if (aba === 'CARTEIRA' && ehCelulaDaPaleta_(e.range)) {
    continuarPaleta_(inicio, e.oldValue, true, null, e.value);
    return;
  }
  if (typeof r53EditarCaminho_ === 'function' && r53EditarCaminho_(e)) return;
  if (!e.r53EditorVerificado_ && typeof r53Editar_ === 'function' && r53Editar_(e)) return;
  // 01/10/2026: a FICHA PESSOAL tem as caixas de treino, as missões que sobem o nível e as notas que mudam.
  if (aba === ABA_PESSOAL_) {
    try { devolverConta_(e, ABA_PESSOAL_); } catch (err) { console.log('ficha pessoal, a conta: ' + err.message); }
    try { textoDaCapacidade_(e); } catch (err) { console.log('ficha pessoal, a Origem: ' + err.message); }
    try { esticarCaixas_(e, ABA_PESSOAL_); } catch (err) { console.log('ficha pessoal, a caixa que estica: ' + err.message); }
    try { pessoalEditada_(e); } catch (err) { console.log('ficha pessoal: ' + err.message); }
    continuarPaleta_(inicio, null, false, e.range);
    return;
  }
  // 01/10/2026: a caixa calculada da FICHA AMALDIÇOADA em que alguém digitou volta a ser a conta.
  if (aba === ABA_AMALDICOADA_) {
    try {
      devolverConta_(e);
      // 07/10/2026: o salto em que alguém escreveu por cima volta a ser a ligação até a seção
      if (e.range.getRow() <= LINHA_DOS_SALTOS_) ligarSaltosDe_(SpreadsheetApp.getActive(), ABA_AMALDICOADA_, DADOS_DA_AMALDICOADA_, null, e.range);
    } catch (err) { console.log('ficha amaldiçoada: ' + err.message); }
    continuarPaleta_(inicio, null, false, e.range);
    return;
  }
  // 06/10/2026: a INVOCAÇÕES é como a FICHA AMALDIÇOADA: a conta mora na aba oculta dela, e a caixa calculada volta.
  if (aba === ABA_INVOCACOES_) {
    try { familiasCustomDaInvocacao_(e); } catch (err) { console.log('famílias custom: ' + err.message); }
    try { notasDosTipos_(e); } catch (err) { console.log('tipo de entidade: ' + err.message); }
    try { redutorDaInvocacao_(e); } catch (err) { console.log('invocações, a caixa de ±: ' + err.message); }
    try {
      // a linha da lista do conjunto volta como referência, sem a ligação até a ficha: a ligação é refeita na hora
      if (devolverConta_(e, ABA_INVOCACOES_) && e.range.getColumn() <= COLUNA_DA_LISTA_DE_INVOCACOES_) {
        ligarSaltosDe_(SpreadsheetApp.getActive(), ABA_INVOCACOES_, DADOS_DA_INVOCACAO_, null, e.range);
      }
    } catch (err) { console.log('invocações: ' + err.message); }
    try { prenderTemp_(e); } catch (err) { console.log('invocações, TEMP: ' + err.message); }
    continuarPaleta_(inicio, null, false, e.range);
    return;
  }
  // 14/10/2026 (B47): a ANALISE é toda conta, para o bot: quem escrever nela recebe a conta de volta
  if (aba === 'ANALISE') {
    try { devolverConta_(e, 'ANALISE'); } catch (err) { console.log('analise: ' + err.message); }
    return;
  }
  // B47: somente as contas voltam; os campos dos efeitos continuam editáveis.
  if (aba === 'CONFIGURAÇÃO' || aba === 'DADOS_CONFIG' || aba === 'DADOS_CUSTOM' || aba === 'DADOS_PROGRESSAO' || aba === 'DADOS_CRIACAO' || aba === 'DADOS_MELHORIAS' || aba === 'DADOS_RESTRICOES' || aba === 'DADOS_DANOS' || aba === 'DADOS_FORMAS' || aba === 'DADOS_APTIDOES' || aba === 'DADOS_TALENTOS' || aba === 'DADOS_ENTIDADES') {
    try { devolverConta_(e, aba); } catch (err) { console.log('configuração: ' + err.message); }
    if (aba === 'CONFIGURAÇÃO') {
      try { notasDosTipos_(e); } catch (err) { console.log('tipo custom: ' + err.message); }
      // 26/10/2026: as cartas antes das caixas que esticam. As duas leem antes de gravar, e as cartas gravam na FICHA,
      // não aqui: na ordem de antes, a leitura das cartas esperava o recálculo das alturas gravadas (~4,5 s).
      var specConfig = ABAS.filter(function (s) { return s.nome === 'CONFIGURAÇÃO'; })[0];
      if ((specConfig && specConfig.gatilhos_habilidades || ['B737:O792']).some(function (a1) { return tocaFaixa_(e.range, a1); })) {
        try { if (!habilidadeCustomForaDeUso_(e)) habilidadesDaFicha_(e, indiceEstatico_() || indice(), true); } catch (err) { console.log('cartas custom: ' + err.message); }
      }
      try { esticarCaixas_(e, aba); } catch (err) { console.log('texto custom: ' + err.message); }
    }
    continuarPaleta_(inicio, null, false, e.range);
    return;
  }
